def add_gradient_banner(slide, x, y, w, h):
    """Full-width footer banner — exact 4-stop linear gradient (0% TEAL → 74% NAVY →
    83% NAVY → 100% NAVY) copied from the July 2026 webinar deck master's Rectangle 4.
    python-pptx's high-level gradient API only supports 2 stops cleanly, so this builds
    the <a:gradFill> XML directly to match the source exactly."""
    from pptx.oxml.ns import qn
    shape = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, Inches(x), Inches(y), Inches(w), Inches(h))
    shape.line.fill.background()
    shape.shadow.inherit = False
    style_el = shape._element.find(qn('p:style'))
    if style_el is not None:
        shape._element.remove(style_el)
    spPr = shape.fill._xPr
    # remove whatever fill python-pptx put there by default
    for tag in ("a:noFill", "a:solidFill", "a:gradFill", "a:blipFill", "a:pattFill"):
        el = spPr.find(qn(tag))
        if el is not None:
            spPr.remove(el)
    grad_xml = (
        '<a:gradFill xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" flip="none" rotWithShape="1">'
        '<a:gsLst>'
        '<a:gs pos="0"><a:srgbClr val="02A7C2"/></a:gs>'
        '<a:gs pos="74000"><a:srgbClr val="083D5F"/></a:gs>'
        '<a:gs pos="83000"><a:srgbClr val="083D5F"/></a:gs>'
        '<a:gs pos="100000"><a:srgbClr val="083D5F"/></a:gs>'
        '</a:gsLst>'
        '<a:lin ang="0" scaled="1"/>'
        '<a:tileRect/>'
        '</a:gradFill>'
    )
    grad_el = parse_xml(grad_xml)
    # gradFill must come right after prstGeom in the schema sequence
    prstGeom = spPr.find(qn("a:prstGeom"))
    prstGeom.addnext(grad_el)
    return shape

def add_section_footer_banner(slide, chevron_bytes):
    """The section-divider footer treatment from the webinar master, scaled to bmap's
    10x5.625 canvas (webinar master is 13.333x7.5 — same 0.75 scale factor both axes)."""
    add_gradient_banner(slide, 0, 5.149, 10.0, 0.476)
    add_chevron_mark(slide, 0, 5.150, 0.476, chevron_bytes)
    add_text(slide, "Verlocity.ai", 0.566, 5.297, 2.2, 0.189,
             size=7, bold=True, italic=True, color=WHITE, font="Inter")
    add_text(slide,
             f"Confidential  ·  Verlocity Princeton Partners Group  ·  {datetime.now().year}",
             2.6, 5.297, 4.8, 0.189, size=7.5, color=WHITE, align=PP_ALIGN.CENTER)

# ═══════════════════════════════════════════════════════════════
# DATA FETCH
# ═══════════════════════════════════════════════════════════════
def _fetch_brokered(ik):
    """
    Fetch brokered deposit data from raw_schedule_RCE + raw_schedule_RC.
    Returns dict with brokered metrics, or None if below 15% threshold.
    Uses RCON2365 (brokered deposits) / RCON2385 (total deposits RCE).
    All values in $thousands from FFIEC call report.
    """
    THRESHOLD = 0.15   # 15% — meaningful brokered pressure

    # Extract RSSDID from inst_key (bank_463735 → 463735)
    rssdid = ik.replace("bank_", "").replace("cu_", "")

    # Use Supabase RPC-style SQL via the raw PostgREST endpoint
    # We'll query raw_schedule_RCE directly
    url = (
        f"{SUPA_URL}/rest/v1/raw_schedule_RCE"
        f'?IDRSSD=eq.{rssdid}'
        f'&period=eq.2025-12-31'
        f'&select=RCON2365,RCON2385,RCON0352,RCON5590'
        f'&limit=1'
    )
    import requests as _req
    try:
        r = _req.get(url,
            headers={"apikey": SUPA_KEY, "Authorization": f"Bearer {SUPA_KEY}", "Accept-Profile": "raw"},
            timeout=15)
        rows = r.json()
    except Exception as e:
        print(f"  [brokered] fetch error: {e}")
        return None

    if not rows:
        return None

    row = rows[0]
    try:
        brokered  = float(row.get("RCON2365") or 0)   # $thousands
        total_dep = float(row.get("RCON2385") or 0)   # $thousands
        savings   = float(row.get("RCON0352") or 0)   # $thousands
        cds       = float(row.get("RCON5590") or 0)   # $thousands
    except (TypeError, ValueError):
        return None

    if total_dep == 0:
        return None

    brok_pct = brokered / total_dep

    if brok_pct < THRESHOLD:
        return None   # below threshold — don't show module

    return {
        "brokered_M":   round(brokered   / 1000, 1),   # convert to $M
        "total_dep_M":  round(total_dep  / 1000, 1),
        "savings_M":    round(savings    / 1000, 1),
        "cds_M":        round(cds        / 1000, 1),
        "brokered_pct": round(brok_pct * 100, 1),
    }


def fetch_all_bank_competitors(ik):
    """Bank-wide competitor rows (every branch, not just one) — used for
    BOTH the scatter chart (needs real volume to show anything) and the
    whole-footprint 'Top 2 Peers to Watch' selection (needs the full pool,
    not just the ~3 competitors near a single branch, to make a genuine
    'most exposed anywhere in your network' claim).

    Sorted by vuln_score server-side with a high limit — this guarantees
    the true top-N by vulnerability is captured even for the largest banks
    in the system (up to 14,330 competitor rows for one institution),
    without needing to fetch every single row to find the top 2."""
    return supabase("branch_target_competitors",
        f"my_inst_key=eq.{ik}&select=target_namefull,target_namebr,target_inst_key,"
        "target_dist_mi,vuln_score,target_yoy_pct,target_roa,target_noncurrent_pct"
        "&order=vuln_score.desc&limit=1000")


def fetch_branch_competitors(my_branch_id):
    """Competitors near one specific branch (the 'lead office'), with each
    competitor's own opportunity score and vulnerability score — distinct
    from vw_network_top_targets, which is a single bank-wide aggregate.
    Pulls the raw signal columns too (not just the final scores) so the
    deck can explain WHY a competitor is vulnerable, not just state a number.
    Also pulls target_inst_key so callers can filter to genuine peer-sized
    institutions — proximity alone can surface a branch of a money-center
    bank (e.g. Santander) next to a small community bank, which undercuts
    credibility on first contact even when the branch-level numbers qualify."""
    if not my_branch_id:
        return []
    return supabase("branch_target_competitors",
        f"my_branch_id=eq.{my_branch_id}&select=target_namefull,target_namebr,"
        "target_opp_score,vuln_score,target_dist_mi,target_zone,target_institution_type,"
        "target_yoy_pct,target_roa,target_noncurrent_pct,target_inst_key"
        "&order=target_opp_score.desc&limit=8")


def filter_to_peer_institutions(competitors, client_inst_key, min_ratio=0.1, max_ratio=8.0):
    """Keeps only competitors whose total institution size (not just their
    one nearby branch's deposits) is within a believable peer range of the
    client bank. A single branch's local deposits can look comparable even
    when the parent institution is a national/money-center bank — this
    filters on the actual institution, which is what a first-time viewer
    is really judging when they see a name on this slide.

    Uses summed branch-level FDIC deposits (institution_total_deposits RPC)
    rather than bank_financial_snapshot_latest.total_assets — that column
    is NULL for exactly the institutions this filter most needs to catch
    (e.g. Santander Bank, N.A. has no total_assets row in that table, but
    its 400 branches' summed deposits — $79.5B vs. a $5.5B client — make
    the size mismatch obvious once measured the right way).

    If a competitor's total deposits can't be found, it's kept rather than
    dropped — missing data is far more common for small/thinly-covered
    institutions than for the mega-banks this filter is meant to catch."""
    if not competitors:
        return competitors

    keys = sorted({client_inst_key} | {c.get("target_inst_key") for c in competitors if c.get("target_inst_key")})
    try:
        import urllib.parse
        keys_arr = urllib.parse.quote("{" + ",".join(keys) + "}", safe="")
        rows = supabase("rpc/institution_total_deposits", f"keys={keys_arr}")
    except Exception as e:
        print(f"  Could not fetch institution deposit totals for peer filtering: {e}")
        return competitors

    deposits_by_key = {r["inst_key"]: float(r["total_deposits"]) for r in rows if r.get("total_deposits")}
    client_deposits = deposits_by_key.get(client_inst_key)
    if not client_deposits:
        return competitors  # can't establish a peer band — show everything rather than guess

    lo, hi = client_deposits * min_ratio, client_deposits * max_ratio
    kept = []
    for c in competitors:
        deposits = deposits_by_key.get(c.get("target_inst_key"))
        if deposits is None or lo <= deposits <= hi:
            kept.append(c)
    return kept

def fetch_bank_data(ik):
    print(f"  Fetching branch data...")
    rows = supabase("branch_opportunity_base",
        f"inst_key=eq.{ik}&select=namefull,latest_dep,yoy_deposits,avg_comp_yoy,"
        "opportunity_score,opportunity_zone,market_growth_score,inv_density_norm_winsor")

    print(f"  Fetching branch details...")
    # limit raised from 50 to 5000 (the largest bank in the system has 4,978
    # branches) — the old cap of 50, combined with sorting by opportunity_score
    # descending, silently cut off every Defend/Justify branch for any bank
    # with 50+ branches, since those zones score lowest by definition. That's
    # why _build_branch_list's "top 2 Defend/Justify" slot came back empty
    # for Hancock Whitney (181 branches) — its lowest-scoring branches were
    # never fetched in the first place, not filtered out on purpose.
    br = supabase("branch_opportunity_base",
        f"inst_key=eq.{ik}&select=uninumbr,namebr,citybr,stalpbr,latest_dep,"
        "yoy_deposits,opportunity_score,opportunity_zone,matrix_quadrant,priority_tier,campaign,"
        "household_income,yoy_income_growth,zhvi,zhvi_yoy_pct,total_population,yoy_pop_growth"
        "&order=opportunity_score.desc&limit=5000")

    print(f"  Fetching network target...")
    tgt_arr = supabase("vw_network_top_targets",
        f"my_inst_key=eq.{ik}&select=target_institution,branches_in_radius,"
        "avg_vuln_score,avg_yoy_pct,target_roa,target_efficiency_ratio,dominant_zone"
        "&order=network_rank.asc&limit=1")

    print(f"  Fetching financials...")
    fin_arr = supabase("bank_financial_snapshot_latest",
        f"inst_key=eq.{ik}&select=*&limit=1")

    print(f"  Fetching brokered deposits...")
    brok = _fetch_brokered(ik)

    return {
        "ik":       ik,
        "bankName": rows[0].get("namefull", ik) if rows else ik,
        "rows":     rows or [],
        "br":       br   or [],
        "tgt":      tgt_arr[0] if tgt_arr else None,
        "fin":      fin_arr[0] if fin_arr else {},
        "brokered": brok,
    }

# ═══════════════════════════════════════════════════════════════
# AI NARRATIVES
# ═══════════════════════════════════════════════════════════════
def get_narratives(data):
    if not ANTH_KEY:
        print("  ⚠  No ANTHROPIC_API_KEY — using placeholder narratives")
        empty = {"headline":"","spoken":"","bullets":[],"close":""}
        return {k: empty for k in ["network","priority","financial","nextsteps"]}

    rows = data["rows"]; fin = data["fin"]; tgt = data["tgt"]
    br   = data["br"];   bankName = data["bankName"]

    def sf(v, default=0):
        try:
            return float(v) if v is not None else default
        except (TypeError, ValueError):
            return default

    tot      = sum(sf(r.get("latest_dep")) for r in rows)
    avg      = lambda v: sum(sf(r.get(v)) for r in rows) / max(len(rows),1)
    invest   = sum(1 for r in rows if r.get("opportunity_zone")=="Invest")
    analyze  = sum(1 for r in rows if r.get("opportunity_zone")=="Analyze")
    defend   = sum(1 for r in rows if r.get("opportunity_zone")=="Defend")
    justify  = sum(1 for r in rows if r.get("opportunity_zone")=="Justify")
    bankYoY  = avg("yoy_deposits")*100
    compYoY  = avg("avg_comp_yoy")*100
    gap      = bankYoY - compYoY
    avgScore = avg("opportunity_score")

    sig_br = [b for b in br if sf(b.get("latest_dep")) >= 5e6]
    top3 = sorted(sig_br or br, key=lambda b: sf(b.get("opportunity_score")), reverse=True)[:3]
    top3_str = "; ".join(
        f"{b['namebr'].split('--')[-1].strip()} "
        f"(${sf(b.get('latest_dep'))/1e6:.0f}M, "
        f"{sf(b.get('yoy_deposits'))*100:.1f}% YoY, "
        f"score {sf(b.get('opportunity_score')):.0f})"
        for b in top3
    )

    comp_str = (
        f"Primary competitor — {tgt['branches_in_radius']} overlap branches, "
        f"avg vulnerability score {sf(tgt.get('avg_vuln_score')):.0f}/100, "
        f"their YoY {sf(tgt.get('avg_yoy_pct')):.1f}%"
    ) if tgt else "N/A"

    brok = data.get("brokered")
    brok_str = (
        f"Brokered deposits: {brok['brokered_pct']}% of total "
        f"(${brok['brokered_M']:.0f}M of ${brok['total_dep_M']:.0f}M total). "
        f"Direct savings base: ${brok['savings_M']:.0f}M. "
        f"Conversion opportunity: replace expensive brokered funding with "
        f"direct customer deposits via savings→CD funnel strategy."
    ) if brok else "Brokered deposits: not a material factor for this bank."

    ctx = f"""Bank: {bankName} | {len(rows)} branches | ${tot/1e9:.2f}B deposits
Deposit YoY: +{bankYoY:.1f}% | Peer avg (competitor growth in bank\'s own markets): +{compYoY:.1f}% | Gap: {gap:+.1f}pp
Avg opp score: {avgScore:.1f}/100 | Zones: Invest {invest} | Analyze {analyze} | Defend {defend} | Justify {justify}
ROA: {fin.get('roa','—')}% | NIM: {fin.get('nim','—')}% | Efficiency: {fin.get('efficiency_ratio','—')}%
Net income YoY: {fin.get('net_income_yoy_pct','—')}% | Tier 1: {fin.get('tier1_capital_pct','—')}%
Primary competitor: {comp_str}
Brokered deposit situation: {brok_str}
Top 3 branches: {top3_str}"""

    system = """You are BMAP Executive Strategist at Verlocity Princeton Partners Group. Write boardroom-quality slide narratives grounded in exact numbers. These slides open conversations — they inform, they don't pressure. Never prescribe specific actions the bank can execute without Verlocity. Name the opportunity clearly and let the data make the case; avoid hype language, urgency gimmicks, or anything that reads as a sales pitch rather than an analysis.

VERLOCITY PLATFORM CONTEXT (reference naturally where relevant):
Verlocity's marketing intelligence platform is built around four capabilities, all live today:
- BMAP — Market Truth: branch-level scoring across deposits, growth, and competitive density; where to invest, defend, and exit.
- AudienceFinder & MediaPredict — Media Performance: precision-targeted depositor campaigns built on the audiences BMAP identifies, converting savings openers into sticky CD relationships.
- Omnibranch — Branch Orchestration: unifies deposit data, market signals, and campaign execution into one operating view across the network.
- Predictive ROI — Accountability: forecasts the return on marketing spend before it happens, then tracks performance against that forecast.
The BMAP Snapshot is the entry point — it's the data layer the other three capabilities act on.
When writing nextsteps, position Verlocity as the partner that turns BMAP's market read into targeted campaigns (AudienceFinder/MediaPredict), coordinated execution (Omnibranch), and measurable return (Predictive ROI). Reference the platform naturally — the bank is seeing BMAP; help them understand what it connects to.
WinShare model: Verlocity invests alongside the bank — compensation tied to results, not effort.

BROKERED DEPOSIT CONTEXT (use if brokered pressure is present):
Brokered deposits are expensive, rate-sensitive, and leave when a better rate appears. The savings→CD funnel strategy converts brokered volume to sticky direct customer deposits at lower cost. If brokered pressure is present, frame it as a funded account conversion opportunity for AudienceFinder and MediaPredict campaigns targeting savings account openers who convert to CDs.

IMPORTANT RULES:
- Never name competitors directly. Refer to them as "your primary competitor" or "a regional competitor".
- Never prescribe specific budget reallocation amounts or staff actions.
- Bullets reveal WHAT the data shows, not HOW to fix it.
- Close bars end with a genuine question or invitation to discuss — never a pressure tactic or implied cost of inaction. 160-190 characters max, one sentence — this is a small dark bar at the bottom of the slide, not room for a paragraph.
- "Peer avg" means competitor deposit growth in the bank's own markets.
- nextsteps headline: make it about what the Verlocity platform delivers as a whole, not just BMAP.
- nextsteps spoken: 300-330 characters max, factual tone. Note that BMAP is the data foundation the other three capabilities build on.
- nextsteps bullets: each bullet names one of the four capabilities and the concrete outcome it drives.
- nextsteps close: invite a conversation about next steps — direct and respectful, not a hard sell. 160-190 characters max, one sentence.

Return ONLY valid JSON — no markdown, no explanation:
{"slides":[
  {"id":"network","headline":"strong claim max 9 words","spoken":"ONE sentence, 300-330 characters max. The single sharpest number and comparison Tom would say walking in — do not stack multiple metrics. Factual tone, must read naturally aloud in one breath.","bullets":["data point with number","competitive threat — no competitor name","gap or risk that needs Verlocity to solve"],"close":"ONE sentence, 160-190 characters max. A genuine question or invitation to dig deeper — not a prescription, not a directive."},
  {"id":"priority","headline":"...","spoken":"...","bullets":[...],"close":"..."},
  {"id":"financial","headline":"...","spoken":"...","bullets":[...],"close":"..."},
  {"id":"nextsteps","headline":"...","spoken":"...","bullets":[...],"close":"..."}
]}"""

    print(f"  Generating AI narratives...")
    client = anthropic.Anthropic(api_key=ANTH_KEY)
    msg = client.messages.create(
        model="claude-sonnet-4-6",
        max_tokens=2400,
        system=system,
        messages=[{"role":"user","content":f"Generate 4-slide narratives for:\n\n{ctx}"}]
    )
    raw = msg.content[0].text.strip().replace("```json","").replace("```","").strip()
    narr = {}
    try:
        for s in json.loads(raw)["slides"]:
            narr[s["id"]] = s
    except Exception as e:
        print(f"  ⚠  JSON parse failed ({e}) — using empty narratives")
    N = lambda k: narr.get(k, {"headline":"","spoken":"","bullets":[],"close":""})
    result = {k: N(k) for k in ["network","priority","financial","nextsteps"]}

    # Safety net: each text box on the slide has a fixed size, so it has a
    # hard ceiling on how many characters it can hold before autofit
    # shrinking hits its practical floor and text overflows instead of
    # shrinking cleanly. The prompt asks the model to stay under these
    # limits, but it doesn't always comply exactly — truncating here
    # guarantees a box never receives more than it can actually hold,
    # regardless of what comes back from the API.
    #
    # Limits below are per FIELD, applied to every slide ("by slide by box"
    # in practice, since every slide uses the same box sizes today — if a
    # future slide type uses a differently-sized box for one of these
    # fields, give that field its own per-slide-id entry here rather than
    # changing the box size without updating the limit).
    #
    #   field    box size (w x h)      max chars before overflow risk
    #   spoken   5.6" x 0.62", 9.5pt   ~330
    #   close    5.4" x 0.46", 9.5pt   ~224 — smaller box, tighter limit
    FIELD_CHAR_LIMITS = {
        "spoken": 330,
        "close":  210,   # slight safety margin under the ~224 hard ceiling
    }
    for k in result:
        for field, limit in FIELD_CHAR_LIMITS.items():
            text = result[k].get(field, "")
            if len(text) > limit:
                print(f"  ⚠  '{k}.{field}' was {len(text)} chars — truncating to {limit}")
                result[k][field] = truncate_label(text, limit)

    return result

