def build_cover(prs, d, logo_bytes, transparent_logo_bytes=None, chevron_bytes=None):
    """Cover slide — fixed template, identical on every deck regardless of
    bank (per direct instruction: slides 1-6 and 14 are not bank-custom,
    always the same). The Verlocity logo, tagline, and "BMAP Snapshot"
    title are already baked into the branded background graphic, so
    nothing else is drawn on top except the page number, kept for
    consistency with every other slide's footer numbering."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])  # blank
    slide.shapes.title and slide.shapes.title.element.getparent().remove(slide.shapes.title.element)

    cover_bg_bytes = fetch_cover_bg()
    if cover_bg_bytes:
        slide.shapes.add_picture(io.BytesIO(cover_bg_bytes), Inches(0), Inches(0), Inches(10), Inches(5.625))
    elif transparent_logo_bytes:
        # Fallback if the background asset ever fails to decode
        add_transparent_logo(slide, 8.34, 0.072, 0.701, transparent_logo_bytes)

    # Page number — cover is page 1 of the deck, kept consistent with
    # every other slide's visible footer number. Dark navy since it sits
    # over the background graphic's white wedge, bottom-right.
    add_text(slide, "1", 9.30, 5.30, 0.55, 0.20, size=9, color=NAVY, align=PP_ALIGN.RIGHT)


