def build_bmap_overview(prs, d, logo_bytes, page_num=2, transparent_logo_bytes=None, chevron_bytes=None):
    """Explainer — the problem BMAP solves and what it does, two columns
    styled after the Executive Leave-Behind's own layout: regular-weight
    body copy, with a single bold italic pull-quote carrying the emphasis
    rather than the whole paragraph. Closes on the real data-table count
    (24, not the 6 source families) and a line connecting public data
    ("where") to first-party data ("who") — Marc's ask from the demo,
    kept concrete rather than a vague "gets sharper" close."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    add_text(slide, "BMAP: Know Where to Win Before You Spend",
             0.39, 0.30, 7.5, 0.375, size=21, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    # ── Two columns: The Problem | What BMAP Does ──
    y = 0.94
    col_w = 4.35
    col_gap = 0.45
    col_x = [0.39, 0.39 + col_w + col_gap]

    add_text(slide, "THE PROBLEM", col_x[0], y, col_w, 0.16, size=8, bold=True, color=GRAY3)
    add_text(slide, "WHAT BMAP DOES", col_x[1], y, col_w, 0.16, size=8, bold=True, color=GRAY3)
    y += 0.26

    add_text(slide,
             "Most community banks allocate marketing budgets by tradition, not by data. "
             "The result is predictable: equal investment across unequal opportunities, "
             "wasted spend in markets where the battle is already lost, and missed growth "
             "where conditions are ripe to win.",
             col_x[0], y, col_w, 1.55, size=11, color=NAVY, shrink_to_fit=True)
    add_text(slide,
             "BMAP is a branch-level market intelligence platform that gives bank "
             "leadership a precise, data-driven answer to the most important question "
             "in deposit growth strategy.",
             col_x[1], y, col_w, 1.15, size=11, color=NAVY, shrink_to_fit=True)

    # ── Pull-quote — centered across the full width, not confined to the
    # right column, since it's the single unifying line for the slide ──
    quote_y = y + 1.55
    add_text(slide, "Where should we invest our marketing capital — and where should we not?",
             0.39, quote_y, 9.22, 0.44, size=14, bold=True, italic=True, color=NAVY,
             align=PP_ALIGN.CENTER, shrink_to_fit=True)
    y = quote_y + 0.68

    add_rect(slide, 0.39, y, 9.22, 0.03, TEAL)
    y += 0.24

    # ── Table-count stat — restrained card treatment matching the KPI
    # tiles used elsewhere in the deck (e.g. the Deposit Gap slide), not
    # a giant billboard number. "24" spans the full card height so it's
    # vertically centered against the card itself. Label+description are
    # centered as a block too. Card enlarged slightly now that the whole
    # slide has more room to breathe. ──
    card_h = 0.95
    add_rounded_rect(slide, 0.39, y, 9.22, card_h, CARD_BG)

    # "24" built directly (not via add_text) so word_wrap can be forced
    # off — add_text always sets word_wrap=True, which at this font size
    # wrapped "24" into a stacked "2" / "4" inside too narrow a box.
    num_tb = slide.shapes.add_textbox(Inches(0.95), Inches(y), Inches(1.0), Inches(card_h))
    num_tf = num_tb.text_frame
    num_tf.word_wrap = False
    from pptx.enum.text import MSO_ANCHOR
    num_tf.vertical_anchor = MSO_ANCHOR.MIDDLE
    num_p = num_tf.paragraphs[0]
    num_p.alignment = PP_ALIGN.LEFT
    num_r = num_p.add_run(); num_r.text = "24+"
    num_r.font.bold = True; num_r.font.size = Pt(27); num_r.font.color.rgb = TEAL
    num_r.font.name = "Inter"

    add_text(slide, "DATA SOURCES FUSED INTO ONE SCORING ENGINE", 2.05, y + 0.135, 6.7, 0.28,
             size=11, bold=True, color=NAVY, shrink_to_fit=True)
    add_text(slide,
             "FDIC  ·  FFIEC  ·  NCUA  ·  US Census  ·  US Labor  ·  US Housing  ·  Zillow  ·  PostGIS",
             2.05, y + 0.455, 6.7, 0.36, size=10, color=GRAY3, shrink_to_fit=True)


def build_bmap_framework(prs, d, logo_bytes, page_num=4, transparent_logo_bytes=None, chevron_bytes=None):
    """Explainer — the exact Opportunity Score formula and zone quartiles,
    transcribed from Brock's BMAP_Introduction_Slides.pptx slide 3
    verbatim (weights, component descriptions, and zone actions), restyled
    to this deck's branding. Per direct instruction, includes the literal
    weighted formula and percentages — an earlier version of this slide
    kept those out for a CFO audience; that guardrail was intentionally
    overridden here."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    add_text(slide, "How the Opportunity Score & Zones Are Built",
             0.39, 0.30, 7.5, 0.375, size=21, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    SLATE = rgb("334155")

    y = 1.02
    add_text(slide, "OPPORTUNITY SCORE  =  weighted sum of four state-normalized components",
             0.39, y, 9.22, 0.16, size=9, bold=True, color=TEAL, align=PP_ALIGN.CENTER,
             shrink_to_fit=True)
    y += 0.26
    add_text(slide,
             "0.25 × Market Growth  +  0.30 × Relative Growth  +  0.25 × Inverted Density  "
             "+  0.20 × Deposit Size",
             0.39, y, 9.22, 0.30, size=11, bold=True, color=NAVY, align=PP_ALIGN.CENTER,
             shrink_to_fit=True)
    y += 0.30
    add_text(slide,
             "All components are min-max normalized within the state so every branch is "
             "ranked only against its state peers — never a national average.",
             0.39, y, 9.22, 0.20, size=9, color=GRAY3, align=PP_ALIGN.CENTER,
             shrink_to_fit=True)
    y += 0.40

    components = [
        ("25%", "Market Growth",
         "Population & income momentum in the ZIP. Growing markets expand the deposit pie."),
        ("30%", "Relative Growth",
         "Your deposit YoY minus competitor average in the 10-mile radius. The strongest signal."),
        ("25%", "Inverted Density",
         "Fewer competitors nearby = more room to grow. Winsorized to avoid rural outliers."),
        ("20%", "Deposit Size",
         "Log-scaled absolute deposits. Larger base earns modest credit for established presence."),
    ]
    card_w = 1.95
    card_gap = (9.22 - card_w * 4) / 3
    card_h = 1.5
    for i, (pct, name, desc) in enumerate(components):
        cx = 0.39 + i * (card_w + card_gap)
        add_rounded_rect(slide, cx, y, card_w, card_h, CARD_BG)
        add_rect(slide, cx, y, 0.075, card_h, TEAL)     # left accent bar
        add_text(slide, pct, cx + 0.20, y + 0.11, card_w - 0.34, 0.30, size=15, bold=True,
                 color=TEAL)
        add_text(slide, name, cx + 0.20, y + 0.41, card_w - 0.34, 0.26, size=11, bold=True,
                 color=NAVY, shrink_to_fit=True)
        add_text(slide, desc, cx + 0.20, y + 0.71, card_w - 0.34, 0.75, size=9, color=SLATE,
                 shrink_to_fit=True)
    y += card_h + 0.16

    add_text(slide,
             "ZONES — State community-bank quartiles convert the continuous score into an "
             "actionable posture",
             0.39, y, 9.22, 0.16, size=9, bold=True, color=NAVY, align=PP_ALIGN.CENTER,
             shrink_to_fit=True)
    y += 0.30

    roles = [
        ("INVEST", "Top 25%", "Deploy acquisition resources", ZONE_SOLID["Invest"]),
        ("ANALYZE", "50–75th", "Test, then scale", ZONE_SOLID["Analyze"]),
        ("DEFEND", "25–50th", "Retain, don't acquire", ZONE_SOLID["Defend"]),
        ("JUSTIFY", "Bottom 25%", "Strategic review first", ZONE_SOLID["Justify"]),
    ]
    tile_w = card_w
    tile_gap = card_gap
    tile_h = 1.012
    for i, (lbl, band, action, c) in enumerate(roles):
        tx = 0.39 + i * (tile_w + tile_gap)
        add_rounded_rect(slide, tx, y, tile_w, tile_h, c)  # solid fill, no border, small radius
        add_text(slide, lbl, tx + 0.15, y + 0.112, tile_w - 0.28, 0.225, size=11, bold=True, color=WHITE)
        add_text(slide, band, tx + 0.15, y + 0.375, tile_w - 0.28, 0.188, size=9,
                 color=WHITE, shrink_to_fit=True)
        add_text(slide, action, tx + 0.15, y + 0.637, tile_w - 0.28, 0.225, size=10,
                 color=WHITE, shrink_to_fit=True)


def build_bmap_six_scores(prs, d, logo_bytes, page_num=3, transparent_logo_bytes=None, chevron_bytes=None):
    """Explainer — the six scores BMAP computes, split into the two
    families Brock's intro deck uses: Internal (what to do with your own
    branches) and Competitive (where to attack). Adapted from
    BMAP_Introduction_Slides.pptx slide 2, restyled to this deck's
    branding — no formula, no weights, no full 16-Play grid (Brock's own
    slide 5 was flagged as overkill for this audience; "Play" is
    introduced here as a concept, not enumerated)."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    add_text(slide, "The Five Scores That Drive Every Decision",
             0.39, 0.189, 7.875, 0.338, size=18, bold=True, color=NAVY, valign="bottom")
    add_text(slide, "Two families of scoring, one connected system",
             0.39, 0.486, 7.5, 0.225, size=10, italic=True, color=GRAY3)
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    SLATE = rgb("334155")

    internal = [
        ("01", "Opportunity Score",
         "0–100 ranking of deposit growth potential vs. state peers. Weighted mix of "
         "market growth, relative performance, competition density, and deposit size."),
        ("02", "Zone",
         "Strategic posture from score quartiles: Invest, Analyze, Defend, Justify."),
        ("03", "Matrix Quadrant",
         "Market attractiveness paired with branch performance — explains why the "
         "zone looks the way it does."),
        ("04", "Play",
         "A named campaign prescription from Zone × Quadrant — direct input to media "
         "briefs and budget decisions."),
    ]
    competitive = [
        ("05", "Vulnerability Score",
         "How exposed a competitor branch is to losing deposits. Base = 100 minus "
         "their Opportunity Score, then amplified by declining deposits, low ROA, "
         "credit stress, and proximity."),
    ]

    def score_item(x, y0, w, num, name, desc, item_h, accent):
        badge_d = 0.30
        shp = slide.shapes.add_shape(MSO_SHAPE.OVAL, Inches(x), Inches(y0),
                                      Inches(badge_d), Inches(badge_d))
        shp.fill.solid(); shp.fill.fore_color.rgb = accent
        shp.line.fill.background()
        _no_shadow(shp)
        tf = shp.text_frame
        tf.word_wrap = False
        from pptx.enum.text import MSO_ANCHOR
        tf.vertical_anchor = MSO_ANCHOR.MIDDLE
        tf.margin_left = tf.margin_right = tf.margin_top = tf.margin_bottom = 0
        p = tf.paragraphs[0]
        p.alignment = PP_ALIGN.CENTER
        r = p.add_run(); r.text = num
        r.font.bold = True; r.font.size = Pt(8); r.font.color.rgb = WHITE; r.font.name = "Inter"

        add_text(slide, name, x + 0.38, y0, w - 0.38, 0.225, size=11, bold=True,
                 color=NAVY, shrink_to_fit=True)
        add_text(slide, desc, x + 0.38, y0 + 0.262, w - 0.38, item_h - 0.262,
                 size=9, color=SLATE, shrink_to_fit=True)

    # ── INTERNAL — full-width box, 4 items as a 2x2 grid ──
    box_top = 1.05
    box_h_internal = 2.4
    add_rounded_rect(slide, 0.3, box_top, 9.375, box_h_internal, rgb("E8F7FA"))
    add_text(slide, "INTERNAL — WHAT TO DO WITH YOUR OWN BRANCHES",
             0.45, box_top + 0.113, 9.0, 0.225, size=9, bold=True, color=TEAL, shrink_to_fit=True)

    row_h = 0.9
    grid_y = box_top + 0.45
    inner_pad = 0.55
    grid_gap = 0.6
    cell_w = (9.375 - 2 * (inner_pad - 0.3) - grid_gap) / 2
    cell_x = [0.3 + inner_pad, 0.3 + inner_pad + cell_w + grid_gap]
    grid_positions = [
        (cell_x[0], grid_y), (cell_x[1], grid_y),
        (cell_x[0], grid_y + row_h), (cell_x[1], grid_y + row_h),
    ]
    for (num, name, desc), (gx, gy) in zip(internal, grid_positions):
        score_item(gx, gy, cell_w, num, name, desc, row_h, TEAL)

    # ── COMPETITIVE — full-width box below, single item ──
    box_top2 = 3.6
    box_h_comp = 1.275
    add_rounded_rect(slide, 0.3, box_top2, 9.375, box_h_comp, rgb("EBFEF4"))
    add_text(slide, "COMPETITIVE — WHERE TO ATTACK",
             0.45, box_top2 + 0.112, 9.0, 0.21, size=9, bold=True, color=EMERALD, shrink_to_fit=True)
    num, name, desc = competitive[0]
    score_item(0.3 + inner_pad, box_top2 + 0.45, 9.375 - 2 * (inner_pad - 0.3), num, name, desc, 0.412, EMERALD)


def build_bmap_competitive_intel(prs, d, logo_bytes, page_num=5, transparent_logo_bytes=None, chevron_bytes=None):
    """Explainer — Vulnerability Score and Prospecting Output, transcribed
    from Brock's BMAP_Introduction_Slides.pptx slide 4 verbatim: the exact
    base formula, the full ×1.5/×1.4/×1.3 risk-factor multiplier stack,
    and the 200+/300+ prospecting thresholds. Per direct instruction —
    an earlier version of this slide described these risk factors in
    plain language only; that guardrail was intentionally overridden
    here. Still closes by pointing at the Competitive Overview page
    later in this Snapshot, where this exact scoring is already applied
    to this bank's two most exposed nearby competitors."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    add_text(slide, "Competitive Intelligence: Vulnerability & Prospecting",
             0.39, 0.14, 9.22, 0.50, size=18, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.70, 9.22, 0.03, TEAL)
    add_text(slide, "How BMAP finds exposed competitors, and turns that into ranked targets",
             0.39, 0.77, 9.22, 0.20, size=9, italic=True, color=NAVY_SOFT)

    y = 1.20
    col_w = 4.41
    col_gap = 0.4
    col_x = [0.39, 0.39 + col_w + col_gap]
    pad = 0.18

    # ── Card boxes, matching the treatment on the Six Scores slide —
    # Justify-red for the risk-scoring column, Teal for the output
    # column. box_top now starts below the subtitle (previously it
    # started at 0.87 while the subtitle ran to 0.97, so the box's top
    # edge covered the last ~0.10" of that line). box_h now also fills
    # the space freed by removing the bottom divider/note/callout. ──
    box_top = y - pad
    box_h = 3.95
    add_rect(slide, col_x[0] - pad, box_top, col_w + 2 * pad, box_h, JUSTIFY_L, JUSTIFY, Pt(0.9))
    add_rect(slide, col_x[0] - pad, box_top, col_w + 2 * pad, 0.05, JUSTIFY)
    add_rect(slide, col_x[1] - pad, box_top, col_w + 2 * pad, box_h, rgb("F0FAFB"), TEAL, Pt(0.9))
    add_rect(slide, col_x[1] - pad, box_top, col_w + 2 * pad, 0.05, TEAL)

    add_text(slide, "VULNERABILITY SCORE", col_x[0], y, col_w, 0.18, size=9, bold=True, color=JUSTIFY)
    add_text(slide, "PROSPECTING OUTPUT", col_x[1], y, col_w, 0.18, size=9, bold=True, color=TEAL)
    y += 0.28

    add_text(slide, "How exposed is a competitor branch to losing deposits?",
             col_x[0], y, col_w, 0.34, size=11, bold=True, color=NAVY, shrink_to_fit=True)
    add_text(slide, "Turns vulnerability into ranked acquisition targets",
             col_x[1], y, col_w, 0.34, size=11, bold=True, color=NAVY, shrink_to_fit=True)
    y += 0.54

    # ── Left column: exact base formula + full multiplier stack, each
    # factor as a pill badge (matching the numbered-badge style used on
    # the Six Scores slide) rather than plain colored text. Tracked with
    # a running cursor (vy) so every gap is intentional. ──
    add_text(slide, "Base Score  =  100 − Competitor's Opportunity Score",
             col_x[0], y, col_w, 0.28, size=10.5, bold=True, color=NAVY, shrink_to_fit=True)
    vy = y + 0.46
    add_text(slide, "Then multiply by risk factors that stack:",
             col_x[0], vy, col_w, 0.18, size=8.5, italic=True, color=GRAY3, shrink_to_fit=True)
    vy += 0.40

    multipliers = [
        ("×1.5", "Declining deposits (YoY < 0)"),
        ("×1.4", "ROA below 0.5%"),
        ("×1.3", "Noncurrent assets > 2%"),
        ("×1.3", "Within 1 mile of your branch"),
        ("×1.3", "Same institution type"),
    ]
    pill_w, pill_h = 0.60, 0.30
    for factor, desc in multipliers:
        shp = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, Inches(col_x[0]), Inches(vy),
                                      Inches(pill_w), Inches(pill_h))
        shp.fill.solid(); shp.fill.fore_color.rgb = JUSTIFY
        shp.line.fill.background()
        _no_shadow(shp)
        tf = shp.text_frame; tf.word_wrap = False
        from pptx.enum.text import MSO_ANCHOR
        tf.vertical_anchor = MSO_ANCHOR.MIDDLE
        tf.margin_left = tf.margin_right = tf.margin_top = tf.margin_bottom = 0
        p = tf.paragraphs[0]; p.alignment = PP_ALIGN.CENTER
        r = p.add_run(); r.text = factor
        r.font.bold = True; r.font.size = Pt(10.5); r.font.color.rgb = WHITE; r.font.name = "Inter"
        add_text(slide, desc, col_x[0] + pill_w + 0.14, vy, col_w - pill_w - 0.14, pill_h,
                 size=9.5, color=NAVY, valign="center", shrink_to_fit=True)
        vy += pill_h + 0.10

    # ── Right column: Branch-Level and Network-Level prospecting, using
    # its own running cursor (ry) rather than hand-picked offsets so its
    # two sub-sections can never collide with each other or the box edge. ──
    ry = y
    add_text(slide, "BRANCH-LEVEL", col_x[1], ry, col_w, 0.18, size=8.5, bold=True, color=TEAL)
    ry += 0.28
    add_text(slide,
             "Top 3 competitor branches within 10 miles of each of your branches, "
             "ranked by vulnerability score. Direct input to the media brief for "
             "that location.",
             col_x[1], ry, col_w, 0.85, size=9.5, color=NAVY, shrink_to_fit=True)
    ry += 0.85 + 0.35
    add_text(slide, "NETWORK-LEVEL", col_x[1], ry, col_w, 0.18, size=8.5, bold=True, color=TEAL)
    ry += 0.28
    add_text(slide,
             "Aggregated ranking of competitor institutions across the entire "
             "footprint. Shows total addressable deposits and the single "
             "highest-value institution to target network-wide.",
             col_x[1], ry, col_w, 0.85, size=9.5, color=NAVY, shrink_to_fit=True)


def build_network(prs, d, narr, logo_bytes, page_num=7, transparent_logo_bytes=None, chevron_bytes=None):
    """Network snapshot — same KPI-tile + zone-tile visual language as the
    cover, reused here as the deck's first data slide so a reader who
    skips straight past the cover still gets the headline numbers.
    `narr` is accepted for call-signature compatibility but unused —
    this slide is now purely stat tiles, no AI narrative copy."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    bank_name = d.get("bankName", "")
    add_text(slide, bank_name, 0.39, 0.189, 7.875, 0.338, size=18, bold=True, color=NAVY, valign="bottom")
    add_text(slide, f"BMAP Market Snapshot  ·  {d.get('date','')}", 0.39, 0.486, 7.5, 0.225,
             size=10, italic=True, color=GRAY3)
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    # 4 KPI tiles
    kpis = [
        (d["branchCount"], "BRANCHES"),
        (d["deposits"],    "TOTAL DEPOSITS"),
        (d["avgScore"],    "AVG OPP SCORE"),
        (d["gap"],         "VS PEER AVG"),
    ]
    gap_neg = d["gapNeg"]
    tile_w = 2.25
    tile_gap = 0.15
    y1 = 1.106
    for i, (val, lbl) in enumerate(kpis):
        kx = 0.39 + i * (tile_w + tile_gap)
        add_rounded_rect(slide, kx, y1, tile_w, 1.05, CARD_BG)
        c = JUSTIFY if (i==3 and gap_neg) else NAVY
        add_text(slide, val, kx + 0.075, y1 + 0.15, tile_w - 0.15, 0.488, size=21, bold=True, color=c, align=PP_ALIGN.CENTER)
        add_text(slide, lbl, kx + 0.075, y1 + 0.675, tile_w - 0.15, 0.225, size=8, color=GRAY3, align=PP_ALIGN.CENTER)

    # 4 zone tiles
    ZONE_BLURBS = {
        "INVEST":  "Move now — pour resources in before a competitor beats you to it",
        "ANALYZE": "Dig in — validate the signal, then commit spend with confidence",
        "DEFEND":  "Act fast — shore up share before this competitor takes more of it",
        "JUSTIFY": "Hold the line — don't spend here without hard evidence first",
    }
    zones = [
        (str(d["invest"]),  "INVEST",   ZONE_SOLID["Invest"]),
        (str(d["analyze"]), "ANALYZE",  ZONE_SOLID["Analyze"]),
        (str(d["defend"]),  "DEFEND",   ZONE_SOLID["Defend"]),
        (str(d["justify"]), "JUSTIFY",  ZONE_SOLID["Justify"]),
    ]
    y2 = 2.343
    for i, (val, lbl, c) in enumerate(zones):
        zx = 0.39 + i * (tile_w + tile_gap)
        add_rounded_rect(slide, zx, y2, tile_w, 1.95, c)  # solid fill, no border, small radius
        add_text(slide, val, zx + 0.075, y2 + 0.15, tile_w - 0.15, 0.412, size=21, bold=True, color=WHITE, align=PP_ALIGN.CENTER)
        add_text(slide, lbl, zx + 0.075, y2 + 0.6, tile_w - 0.15, 0.225, size=11, bold=True, color=WHITE, align=PP_ALIGN.CENTER)
        add_text(slide, ZONE_BLURBS[lbl], zx + 0.225, y2 + 0.938, tile_w - 0.45, 0.825, size=9, color=WHITE,
                 align=PP_ALIGN.CENTER, shrink_to_fit=True)




def build_competitive_overview(prs, d, lead_branch, all_competitors, logo_bytes, page_num,
                                transparent_logo_bytes=None, chevron_bytes=None):
    """
    Slide: Competitive Overview.

    Left: whole-footprint quadrant scatter — deposit growth (x, declining
    left / growing right) vs. vulnerability exposure (y, low bottom / high
    top). No axis numbers shown — quadrant position tells the story without
    inviting scrutiny of the underlying score scale. Distance is encoded as
    color instead of a third axis: red <1mi, orange 1-5mi, yellow 5-10mi
    (every competitor in this dataset falls within 10mi, confirmed against
    real data — no need for a 'beyond 10mi' band).

    Right: the two most vulnerable named competitors ANYWHERE in the bank's
    footprint (not just near one branch) — a genuine "most exposed in your
    network" claim rather than "top 2 of the 3 available near one office."
    """
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, "COMPETITIVE OVERVIEW", logo_bytes, transparent_logo_bytes, chevron_bytes)

    add_text(slide, "Competitive Overview", 0.39, 0.30, 7.5, 0.375, size=21, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    SLATE = rgb("334155")

    # ── Scope narrative — data-driven, not AI-generated ──
    n_points = len(all_competitors or [])
    n_inst = len({c.get("target_inst_key") for c in (all_competitors or []) if c.get("target_inst_key")})
    scope_line = (
        f"Across {d['bankName']}'s {d['branchCount']} branches, BMAP is tracking "
        f"{n_points} competitor data points"
        + (f" across {n_inst} institutions" if n_inst else "")
        + " — the two most exposed anywhere in your footprint are called out to the right."
    ) if n_points else "No competitor data available yet."
    add_text(slide, scope_line, 0.39, 0.915, 9.22, 0.45, size=11, color=SLATE, shrink_to_fit=True)

    if not all_competitors:
        add_text(slide, "No competitor data available yet.",
                 0.39, 1.6, 9.22, 0.4, size=11, color=GRAY3)
        return slide

    # ── Competitive Exposure by Distance — compact pill rows, not a
    # point-cloud. The radar/scatter attempts both hit real rendering
    # problems on live data (dot overlap, label collision) once there were
    # enough competitors to be interesting — an aggregate breakdown shows
    # the same real breadth without anything that can visually collide. ──
    add_text(slide, "Competitive Exposure by Distance", 0.39, 1.478, 4.5, 0.225,
             size=10, bold=True, color=NAVY)

    usable = [c for c in all_competitors
              if c.get("target_dist_mi") is not None]

    CHART_X, CHART_W = 0.39, 4.65

    if usable:
        bands = [
            ("< 1 mile",  0.0, 1.0),
            ("1–5 miles", 1.0, 5.0),
            ("5–10 miles", 5.0, 10.0),
        ]

        def _is_vulnerable(c):
            """Two rules, combined with OR — validated against real data on
            two banks (Hancock Whitney 14.8%, Mid Penn Bank 13.5%, both in
            the intended 10-15% range):

            1. MODERATE MULTI-FACTOR: at least 2 of 3 signals present
               (deposits down >8%, ROA below 0.6%, noncurrent assets above
               1.75%). Requiring 2 of 3 (not just 1) matters because a
               single signal — especially deposit decline, which has been
               common industry-wide the last couple years as customers
               moved to money-market funds — was flagging ~75%+ of all
               competitors nationwide and meant nothing.

            2. EXTREME SINGLE-SIGNAL OUTLIER: deposits down >30%, ROA below
               0.2%, or noncurrent above 3.5% — any ONE of these alone is
               rare and real enough to flag on its own. This rule exists
               specifically because the closest competitors (<1 mile) kept
               coming back with zero flags under rule 1 alone: checking the
               actual data, several had dramatic one-year deposit swings
               (one over -49%) but genuinely healthy ROA and credit
               quality — a real, honest finding on its own merit, just not
               a multi-factor one. Rule 2 catches that case without forcing
               a financially healthy institution into a false 'distressed'
               claim just to fill the closest band."""
            yoy = c.get("target_yoy_pct")
            roa = c.get("target_roa")
            noncur = c.get("target_noncurrent_pct")

            signals_hit = 0
            if yoy is not None and float(yoy) < -8:
                signals_hit += 1
            if roa is not None and float(roa) < 0.6:
                signals_hit += 1
            if noncur is not None and float(noncur) > 1.75:
                signals_hit += 1
            if signals_hit >= 2:
                return True

            if yoy is not None and float(yoy) < -30:
                return True
            if roa is not None and float(roa) < 0.2:
                return True
            if noncur is not None and float(noncur) > 3.5:
                return True
            return False

        row_h = 0.45
        row_gap = 0.075
        ry = 1.815
        for label, lo, hi in bands:
            in_band = [c for c in usable if lo <= float(c["target_dist_mi"]) < hi]
            n_total = len(in_band)
            n_vulnerable = sum(1 for c in in_band if _is_vulnerable(c))

            add_rounded_rect(slide, CHART_X, ry, CHART_W, row_h, CARD_BG, radius=0.037)
            add_text(slide, label, CHART_X + 0.15, ry + 0.113, 1.35, 0.225, size=10, bold=True, color=NAVY)
            add_text(slide, f"{n_total} competitor{'s' if n_total != 1 else ''} tracked",
                     CHART_X + 1.575, ry + 0.038, 2.85, 0.188, size=9, color=SLATE)
            if n_total:
                add_text(slide, f"{n_vulnerable} of {n_total} flagged vulnerable",
                         CHART_X + 1.575, ry + 0.225, 2.85, 0.188, size=9, color=TEAL)
            ry += row_h + row_gap

        add_text(slide, "\"Vulnerable\" = multiple warning signs together, or one extreme outlier alone — "
                 "declining deposits, weak profitability, rising credit-quality strain.",
                 0.39, 3.84, 9.22, 0.375, size=9, italic=True, color=GRAY3, shrink_to_fit=True)

    # ── Top 2 by vulnerability — whole footprint, not one branch ──
    top_vuln = sorted(all_competitors, key=lambda c: float(c.get("vuln_score") or 0), reverse=True)[:2]

    right_x, right_w = 5.34, 4.275
    add_text(slide, "Top 2 Peers to Watch", right_x, 1.478, right_w, 0.225,
             size=10, bold=True, color=NAVY, shrink_to_fit=True)

    vy = 1.815
    for i, c in enumerate(top_vuln):
        name = c.get("target_namefull") or c.get("target_namebr") or "—"
        narrative = _sales_narrative(c)

        add_rounded_rect(slide, right_x, vy, right_w, 1.012, CARD_BG)
        add_text(slide, f"{i+1}. {name}", right_x + 0.15, vy + 0.15, right_w - 0.3, 0.262, size=11, bold=True,
                 color=NAVY, shrink_to_fit=True)
        add_text(slide, narrative, right_x + 0.15, vy + 0.45, right_w - 0.3, 0.45, size=10,
                 color=SLATE, shrink_to_fit=True)
        vy += 1.125

    if not top_vuln:
        add_text(slide, "No named competitor data available yet.",
                 right_x, vy, right_w, 0.4, size=8, color=GRAY3, shrink_to_fit=True)

    return slide


def build_branches(prs, d, narr, logo_bytes, page_num=9, transparent_logo_bytes=None, chevron_bytes=None):
    """Priority branches — headline + description + top-3 branch cards +
    a closing line on the Justify-zone count. `narr` kept for signature
    compatibility but unused; headline/paragraph are computed directly
    from d, same pattern as build_next_steps's summary paragraph."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    bank_name = d.get("bankName", "")
    invest, justify, branch_count = d["invest"], d["justify"], d["branchCount"]
    SLATE = rgb("334155")

    headline = f"{invest} branches ready to invest, {justify} need a harder look"
    add_text(slide, headline, 0.39, 0.30, 7.5, 0.375, size=21, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    paragraph = (
        f"BMAP scores every branch on deposit volume, growth trajectory, and competitive "
        f"density — and across {bank_name}'s {branch_count}-branch network, {invest} locations "
        f"score into the Invest zone, meaning the local market conditions actively support "
        f"accelerated deposit capture right now."
    )
    add_text(slide, paragraph, 0.39, 0.929, 9.22, 0.675, size=11, color=SLATE, shrink_to_fit=True)

    top3 = d["branchList"][:3]
    taglines = ["Network's highest-scoring location", "Largest balance in top tier",
                "Consistent growth, smaller base"]
    card_w = 3.0
    card_gap = 0.15
    card_h = 1.65
    y = 1.791
    BRANCH_ACCENT = EMERALD  # fixed accent color on this slide, not zone-mapped
    for i, b in enumerate(top3):
        cx = 0.39 + i * (card_w + card_gap)
        add_rounded_rect(slide, cx, y, card_w, card_h, CARD_BG)
        add_rect(slide, cx, y, 0.09, card_h, BRANCH_ACCENT)   # left accent bar
        add_text(slide, b["name"], cx + 0.225, y + 0.15, card_w - 0.4, 0.3, size=11, bold=True,
                 color=NAVY, shrink_to_fit=True)
        add_text(slide, f"{b['dep']}  ·  {b['yoy']}% YoY  ·  Score {b.get('score','—')}",
                 cx + 0.225, y + 0.563, card_w - 0.4, 0.262, size=10, color=TEAL, shrink_to_fit=True)
        if i < len(taglines):
            add_text(slide, taglines[i], cx + 0.225, y + 0.938, card_w - 0.4, 0.45,
                     size=10, color=SLATE, shrink_to_fit=True)

    close_y = y + card_h + 0.225
    add_text(slide,
             f"{justify} branches sit in the Justify zone — their market scores and growth "
             f"rates raise questions about current positioning that the data surfaces clearly.",
             0.39, close_y, 9.22, 0.45, size=11, color=SLATE, shrink_to_fit=True)


def build_financial(prs, d, narr, logo_bytes, page_num=11, transparent_logo_bytes=None, chevron_bytes=None):
    """Financial fundamentals — headline + description + a single
    full-width metric table. `narr` kept for signature compatibility but
    unused. Drops the old checkmark/benchmark-flag column and the
    competitor/brokered callout boxes to match the clean table-only
    treatment in the final deck."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    bank_name = d.get("bankName", "")
    metrics = d["metrics"]
    m = {mm["label"]: mm for mm in metrics}
    roa_v = m.get("ROA", {}).get("value", "—")
    nim_v = m.get("NIM", {}).get("value", "—")
    ni_v  = m.get("Net Income YoY", {}).get("value", "—")
    SLATE = rgb("334155")

    all_ok = all(mm["ok"] for mm in metrics) if metrics else False
    if all_ok:
        headline = "Strong fundamentals create real room to press the advantage"
        para_tail = ("the kind of balance sheet that can support deliberate, targeted growth "
                     "investment rather than defensive action.")
    else:
        headline = "Fundamentals worth watching alongside the growth opportunity"
        para_tail = "worth factoring into how aggressively to pursue the opportunity ahead."
    paragraph = (f"A {roa_v} ROA, {nim_v} NIM, and net income growth of {ni_v} put {bank_name} "
                 f"in a position of financial standing — {para_tail}")

    add_text(slide, headline, 0.39, 0.30, 7.5, 0.375, size=18, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)
    add_text(slide, paragraph, 0.39, 0.881, 9.22, 0.525, size=11, color=SLATE, shrink_to_fit=True)

    y = 1.593
    cols = [(0.525, 3.0, "METRIC", PP_ALIGN.LEFT), (4.125, 2.25, "VALUE", PP_ALIGN.CENTER),
            (6.75, 2.625, "BENCHMARK", PP_ALIGN.CENTER)]
    add_rect(slide, 0.39, y, 9.22, 0.3, NAVY)
    for cx, cw, cl, ca in cols:
        add_text(slide, cl, cx, y, cw, 0.3, size=9, bold=True, color=WHITE,
                 align=ca, valign="center")
    y += 0.338
    row_h = 0.338
    for i, mm in enumerate(metrics):
        bg = CARD_BG if i % 2 == 0 else WHITE
        add_rect(slide, 0.39, y, 9.22, row_h, bg)
        add_text(slide, mm["label"], 0.525, y, 3.0, row_h, size=10, color=NAVY, valign="center")
        add_text(slide, mm["value"], 4.125, y, 2.25, row_h, size=10, bold=True, color=TEAL,
                 align=PP_ALIGN.CENTER, valign="center")
        add_text(slide, mm["bench"], 6.75, y, 2.625, row_h, size=10, color=GRAY3,
                 align=PP_ALIGN.CENTER, valign="center")
        y += row_h


def build_gap(prs, d, narr, logo_bytes, page_num=8, transparent_logo_bytes=None, chevron_bytes=None):
    """Deposit-gap slide — headline / description / 3 supporting bullets /
    4 stat tiles, all computed directly from d (this slide isn't one of
    the four AI-generated narrative ids, so headline/paragraph text is
    deterministic — same pattern used on build_next_steps). `narr` kept
    for signature compatibility but unused."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    bank_name = d.get("bankName", "")
    gap_neg = d["gapNeg"]
    bank_yoy_f = float(d.get("bankYoY", 0) or 0)
    peer_yoy_f = float(d.get("peerYoY", 0) or 0)
    gap_f = bank_yoy_f - peer_yoy_f
    SLATE = rgb("334155")

    verb = "outgrowing" if not gap_neg else "underperforming"
    headline = f"{bank_name} is {verb} its markets by {abs(gap_f):.1f} points"
    add_text(slide, headline, 0.39, 0.30, 7.5, 0.375, size=21, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    ratio = (bank_yoy_f / peer_yoy_f) if peer_yoy_f else None
    if not gap_neg:
        compare = f"more than {ratio:.0f} times" if ratio and ratio >= 2 else "well above"
        tail = "reflects genuine momentum, not just favorable conditions."
    else:
        compare = "well below"
        tail = "is worth investigating market by market before committing further spend."
    paragraph = (
        f"{bank_name} grew deposits {bank_yoy_f:.1f}% year-over-year — {compare} the "
        f"{peer_yoy_f:.1f}% average competitors recorded in the same markets — a gap of "
        f"{'nearly ' if abs(gap_f) % 1 >= 0.5 else 'about '}{abs(gap_f):.0f} percentage points that {tail}"
    )
    add_text(slide, paragraph, 0.39, 0.893, 9.22, 0.6, size=11, color=SLATE, shrink_to_fit=True)

    lines = [
        f"Deposit base of {d['deposits']} grew {bank_yoy_f:+.1f}% YoY against a peer average "
        f"of {peer_yoy_f:+.1f}% in {bank_name}'s own markets"
    ]
    comp = d.get("competitor")
    if comp:
        comp_yoy = float(comp.get("yoy", 0) or 0)
        action = "contracted" if comp_yoy < 0 else "grew"
        lines.append(
            f"Primary competitor, present in {comp['branches']} overlapping markets, "
            f"{action} {comp_yoy:+.1f}% YoY — a meaningful share-shift opportunity"
        )
    lines.append(
        f"Average opportunity score of {d['avgScore']}/100 across {d['branchCount']} branches "
        f"signals that the network's full growth potential has not yet been captured"
    )

    # Plain paragraph lines — no bullet dots (matches reference)
    y = 1.643
    for line in lines[:3]:
        add_text(slide, line, 0.39, y, 9.22, 0.45, size=11, color=NAVY, shrink_to_fit=True)
        y += 0.525

    # 4 stat tiles
    y = 3.405
    tiles = [
        (f"{bank_yoy_f:+.1f}%", "DEPOSIT YoY"),
        (d["gap"],              "GAP VS PEERS"),
        (d["avgScore"],         "AVG OPP SCORE"),
        (d["branchCount"],      "BRANCHES"),
    ]
    tile_w = 2.25
    tile_gap = 0.15
    for i, (val, lbl) in enumerate(tiles):
        tx = 0.39 + i * (tile_w + tile_gap)
        add_rounded_rect(slide, tx, y, tile_w, 1.125, CARD_BG)
        add_text(slide, val, tx, y + 0.15, tile_w, 0.45, size=20, bold=True, color=TEAL, align=PP_ALIGN.CENTER)
        add_text(slide, lbl, tx, y + 0.675, tile_w, 0.262, size=9, color=GRAY3, align=PP_ALIGN.CENTER)


def build_next_steps(prs, d, narr, logo_bytes, lead_branch=None, top_competitor=None, fin=None,
                      page_num=6, transparent_logo_bytes=None, chevron_bytes=None):
    """
    Closing slide — same proven structure as the Audience Intelligence
    Brief slide (paragraph / where the opportunity is strong / what to
    validate / what this means), reused here rather than inventing a new
    visual treatment. That slide's pattern already works; this one just
    applies it to the whole-deck summary instead of the audience read.

    No call-to-action, no comparison table, no commentary about Verlocity's
    own methodology or depth. The "what to validate" section carries the
    "there's more to see" idea implicitly and honestly — as real scope
    limitations of a single snapshot, not a sales pitch — the same way the
    persona slide is honest about what a first-level read can't confirm.
    """
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    bank_name = d.get("bankName", "")
    SLATE = rgb("334155")

    add_text(slide, f"What This Means for {bank_name}",
             0.39, 0.30, 7.5, 0.375, size=21, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    opp_score = lead_branch.get("opportunity_score") if lead_branch else None
    opp_str = f"{float(opp_score):.0f}" if opp_score is not None else None
    branch_loc = None
    branch_display_name = None
    if lead_branch:
        branch_loc = f"{lead_branch.get('citybr','')}, {lead_branch.get('stalpbr','')}".strip(", ")
        # namebr often comes back as "Bank Name -- Branch Name" — strip to the
        # branch name only, same convention _build_branch_list already uses.
        branch_display_name = lead_branch.get("namebr", "").split("--")[-1].strip() or None

    comp_name, comp_dist, comp_yoy = None, None, None
    if top_competitor:
        comp_name = top_competitor.get("target_namefull") or top_competitor.get("target_namebr")
        comp_dist = top_competitor.get("target_dist_mi")
        comp_yoy = top_competitor.get("target_yoy_pct")

    roa = fin.get("roa") if fin else None
    roa_f = None
    if roa is not None:
        try:
            roa_f = float(roa)
        except (TypeError, ValueError):
            roa_f = None

    # ── Summary paragraph — condensed version of the same facts, one
    # tight paragraph instead of a long narrative block ──
    para_parts = []
    if lead_branch:
        para_parts.append(f"{bank_name}'s strongest opportunity sits at {branch_display_name or 'its top branch'}"
                           f"{f', in {branch_loc}' if branch_loc else ''}.")
    if comp_name:
        decline_phrase = f", down {abs(float(comp_yoy)):.1f}% YoY" if comp_yoy is not None and float(comp_yoy) < 0 else ""
        para_parts.append(f"Nearby, {comp_name} shows real signs of exposure{decline_phrase} — "
                           f"the kind of opening that turns into your gain.")
    if roa_f is not None:
        para_parts.append(f"The bank's own numbers back it up, with ROA at {roa_f:.2f}%.")
    paragraph = " ".join(para_parts) or f"{bank_name}'s branch network shows real, specific opportunity."

    add_text(slide, paragraph, 0.39, 0.855, 9.22, 0.525, size=11, color=SLATE, shrink_to_fit=True)

    # ── Where the opportunity is strong ──
    strong = []
    if lead_branch and opp_str:
        strong.append(f"{branch_display_name or 'Your top branch'} — "
                      f"{lead_branch.get('opportunity_zone','Invest')} zone, opportunity score {opp_str}"
                      f"{f', in {branch_loc}' if branch_loc else ''}.")
    income = lead_branch.get("household_income") if lead_branch else None
    zhvi_yoy = lead_branch.get("zhvi_yoy_pct") if lead_branch else None
    if income is not None and zhvi_yoy is not None:
        strong.append(f"Home values there are climbing {'+' if float(zhvi_yoy) >= 0 else ''}"
                      f"{float(zhvi_yoy):.1f}% a year on just ${float(income)/1000:.0f}K household income "
                      f"— more headroom than it first looks.")
    if d.get("gap"):
        strong.append(f"Deposit growth is already running {d.get('gap')} "
                      f"{'behind' if d.get('gapNeg') else 'ahead of'} peers "
                      f"({d.get('bankYoY','—')}% vs. {d.get('peerYoY','—')}%).")

    y = 1.53
    add_text(slide, "WHERE THE OPPORTUNITY IS STRONG", 0.39, y, 9.0, 0.225,
             size=9, bold=True, color=EMERALD)
    y += 0.30
    for s in strong[:3]:
        add_text(slide, f"→  {s}", 0.39, y, 9.22, 0.262, size=11, color=NAVY, shrink_to_fit=True)
        y += 0.30

    # ── What to validate next — honest scope limits of a single snapshot,
    # same spirit as the persona slide's "where to validate" section, not
    # a sales pitch ──
    validate = []
    if comp_name:
        validate.append(f"{comp_name}'s exposure reflects one year of data — worth confirming how long "
                        f"this has been building before acting on it.")
    if lead_branch:
        validate.append("This Snapshot analyzed one priority branch in depth — validate whether the same "
                        "pattern holds across your other Invest-zone branches.")
    validate.append("ROA and deposit trends here reflect a single point in time — worth tracking quarter "
                    "over quarter, not just once.")

    y = 2.88
    add_text(slide, "WHAT TO VALIDATE NEXT", 0.39, y, 9.0, 0.225,
             size=9, bold=True, color=TEAL)
    y += 0.30
    for s in validate[:3]:
        add_text(slide, f"→  {s}", 0.39, y, 9.22, 0.262, size=11, color=NAVY, shrink_to_fit=True)
        y += 0.30

    # ── What this means — closing synthesis, callout box ──
    synthesis = (
        "Real momentum, in a market where a nearby competitor is visibly struggling — "
        "that's exactly where the immediate opportunity is."
        if lead_branch and top_competitor else
        f"{bank_name}'s branch network shows real, specific opportunity — the kind that's "
        "easy to miss without branch-level data."
    )
    y = 4.155
    box_h = 0.675
    add_rounded_rect(slide, 0.39, y, 9.22, box_h, rgb("E8F7FA"))
    add_text(slide, synthesis, 0.525, y + 0.15, 8.925, 0.375, size=11, bold=True, italic=True, color=NAVY)


def build_activation_steps(prs, d, logo_bytes, page_num=14, transparent_logo_bytes=None, chevron_bytes=None):
    """Closing slide — the four-step activation path from this Snapshot
    into a full Verlocity Growth System engagement. Static process
    content, not derived from bank data. Comes immediately after the
    "What This Means" summary slide (build_next_steps)."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    add_text(slide, "Next Steps for Activating the Verlocity Growth System",
             0.39, 0.30, 7.5, 0.375, size=20, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.75, 9.22, 0.03, TEAL)

    steps = [
        ("1", "Discovery Intake", "Goals, branch profitability, key financial metrics"),
        ("2", "Full BMAP Network Analysis", "Complete scoring across the entire branch network"),
        ("3", "Verlocity Growth System Audit",
         "Product, audience, media, DAO, CRM, and retention readiness"),
        ("4", "Strategy & Tactical Recommendations",
         "Prioritized plays, budgets, and activation roadmap"),
    ]
    y = 1.163
    row_h = 0.899
    badge_d = 0.525
    for i, (num, title, desc) in enumerate(steps):
        shp = slide.shapes.add_shape(MSO_SHAPE.OVAL, Inches(0.525), Inches(y), Inches(badge_d), Inches(badge_d))
        shp.fill.solid(); shp.fill.fore_color.rgb = TEAL
        shp.line.fill.background()
        _no_shadow(shp)
        tf = shp.text_frame; tf.word_wrap = False
        from pptx.enum.text import MSO_ANCHOR
        tf.vertical_anchor = MSO_ANCHOR.MIDDLE
        tf.margin_left = tf.margin_right = tf.margin_top = tf.margin_bottom = 0
        p = tf.paragraphs[0]; p.alignment = PP_ALIGN.CENTER
        r = p.add_run(); r.text = num
        r.font.bold = True; r.font.size = Pt(15); r.font.color.rgb = WHITE; r.font.name = "Inter"

        if i < len(steps) - 1:
            add_rect(slide, 0.735, y + badge_d, 0.09, row_h - badge_d, rgb("B2E5EF"))

        add_text(slide, title, 1.275, y, 7.875, 0.262, size=14, bold=True, color=NAVY)
        add_text(slide, desc, 1.275, y + 0.299, 7.875, 0.225, size=11, color=GRAY3, shrink_to_fit=True)
        y += row_h


def _explainer_card(slide, x, y, w, h, header, items, accent, bg):
    """One card in the 3-column closing layout: colored top bar, header,
    then short punchy bullet lines — same visual language as the
    Investment Framework tiles on page 3. Items are meant to read as
    headlines (one line each), not paragraphs, so the card stays scannable
    rather than turning into a dense block of sentences. Items are
    vertically centered in the space below the header using a fixed line
    height, so a 2-item card (the engine teaser) doesn't stretch its gaps
    awkwardly wide next to the 3-item cards beside it."""
    add_rect(slide, x, y, w, h, bg, accent, Pt(1.0))
    add_rect(slide, x, y, w, 0.05, accent)
    pad = 0.20
    add_text(slide, header, x + pad, y + 0.22, w - 2 * pad, 0.40,
             size=11, bold=True, color=accent, shrink_to_fit=True)

    header_bottom = y + 0.78
    line_h = 0.58
    block_h = line_h * len(items)
    avail_h = (y + h - 0.18) - header_bottom
    iy = header_bottom + max(0, (avail_h - block_h) / 2)

    for it in items:
        shp = slide.shapes.add_shape(MSO_SHAPE.OVAL, Inches(x + pad), Inches(iy + 0.10),
                                      Inches(0.09), Inches(0.09))
        shp.fill.solid(); shp.fill.fore_color.rgb = accent
        shp.line.fill.background()
        _no_shadow(shp)
        add_text(slide, it, x + pad + 0.22, y=iy, w=w - 2 * pad - 0.22, h=line_h - 0.06,
                 size=11.5, bold=True, color=NAVY, valign="top", shrink_to_fit=True)
        iy += line_h


def build_scope_next_steps(prs, d, logo_bytes, page_num, transparent_logo_bytes=None, chevron_bytes=None):
    """Closing slide — adopts the wheel-plus-numbered-cards layout used
    on the deck's own "A System Built to Compound" slide (image left,
    01/02/03 explainer cards right), retargeted for this Snapshot's
    specific job: place the reader (card 01), sell the Assessment
    (card 02), then introduce the Growth Engine (card 03) which the
    wheel visualizes.

    The reference slide's wheel graphic is a flat raster that bakes in
    "Retention & Deepening" — retired in Verlocity_Naming.docx in favor
    of "Loyalty" — so this builds a native circular wheel instead: same
    visual logic (5 capabilities ringing a center hub), current names,
    and it's actual shapes so it can be corrected in one place if naming
    changes again. Card 03's closing line ("a wheel, not a funnel")
    is lifted directly from that reference slide's own card 03, since
    it's the exact right line for what this wheel is showing.

    No pricing, timeline, or CTA language, per the standing rule for
    this slide."""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    bank_name = d.get("bankName", "")

    add_text(slide, "What This Snapshot Is — and What Comes Next",
             0.39, 0.14, 9.22, 0.50, size=18, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.39, 0.70, 9.22, 0.03, TEAL)
    add_text(slide,
             f"Where this Snapshot stands, what a full Assessment adds, and the engine "
             f"it feeds · {bank_name}",
             0.39, 0.77, 9.22, 0.20, size=8.5, italic=True, color=NAVY_SOFT, shrink_to_fit=True)

    # ── Wheel — the actual Verlocity flywheel graphic, used directly per
    # instruction. (Earlier built a native version instead of the
    # existing FLYWHEEL_B64 asset because that decoded to a raster
    # baking in "Retention & Deepening" — retired in favor of "Loyalty"
    # per Verlocity_Naming.docx. This new upload has the same label, so
    # that naming note still stands, but the choice to use it as-is is
    # explicit this time, not something to re-litigate.)
    #
    # BMAP's wedge center was located by sampling this specific image
    # (not assumed): OCR'd it, found the opaque-graphic bounding box in
    # the source PNG (x174–1035, y40–902 of 1224×923), then computed
    # each wedge's center at 60° spacing starting from Brand Reality at
    # -30°/BMAP at +30° and confirmed by sampling pixel color at each
    # computed point — six distinct colors came back, matching the
    # Foundation(green)→Activation(teal)→Momentum(navy) gradient, so the
    # geometry is verified against the actual file, not guessed.
    img_w = 4.0
    img_h = img_w / FLYWHEEL_ASPECT
    img_x = 0.55
    img_y = 1.05 + (3.90 - img_h) / 2
    flywheel_bytes = fetch_flywheel()
    if flywheel_bytes:
        slide.shapes.add_picture(io.BytesIO(flywheel_bytes), Inches(img_x), Inches(img_y),
                                  Inches(img_w), Inches(img_h))

        # BMAP wedge center, in this image's own pixel space -> slide inches
        bmap_fx, bmap_fy = 744 / 1224, 228 / 923
        bmap_x = img_x + bmap_fx * img_w
        bmap_y = img_y + bmap_fy * img_h

        ring_d = 0.62
        hl = slide.shapes.add_shape(MSO_SHAPE.OVAL, Inches(bmap_x - ring_d / 2),
                                     Inches(bmap_y - ring_d / 2), Inches(ring_d), Inches(ring_d))
        hl.fill.background()
        hl.line.color.rgb = WHITE; hl.line.width = Pt(2.5)
        _no_shadow(hl)

        add_text(slide, "▲ you are here", img_x, img_y - 0.24, img_w, 0.18, size=8,
                 italic=True, bold=True, color=TEAL, align=PP_ALIGN.CENTER)
        add_text(slide, "(this Snapshot is the BMAP wedge)", img_x, img_y + img_h + 0.04,
                 img_w, 0.16, size=7, italic=True, color=GRAY3, align=PP_ALIGN.CENTER)

    # ── Numbered explainer cards — right half, same visual language as
    # the reference slide (colored left bar, numbered badge, colored
    # label pill, bold headline, gray description). ──
    cards = [
        ("01", "SNAPSHOT", TEAL, rgb("F0FAFB"),
         "Where you're standing right now",
         "One branch, read in full depth — proof of what BMAP finds across "
         "your whole network."),
        ("02", "FULL ASSESSMENT", INVEST, INVEST_L,
         "Every branch gets this same depth",
         "Every Invest- and Analyze-zone branch scored, ranked, and turned "
         "into a board-ready play — refreshed quarterly."),
        ("03", "GROWTH ENGINE", NAVY, rgb("EAF1F6"),
         "Where BMAP leads",
         "BMAP feeds four more stages that turn market truth into funded, "
         "loyal accounts — a wheel, not a funnel."),
    ]
    cx0 = 4.75
    card_w = 4.55
    card_h = 1.19
    card_gap = 0.14
    card_y0 = 1.05
    for i, (num, label, accent, bg, headline, desc) in enumerate(cards):
        cy0 = card_y0 + i * (card_h + card_gap)
        add_rect(slide, cx0, cy0, card_w, card_h, GRAY1)
        add_rect(slide, cx0, cy0, 0.06, card_h, accent)
        badge_d = 0.34
        add_rect(slide, cx0 + 0.18, cy0 + 0.14, badge_d, badge_d, accent)
        add_text(slide, num, cx0 + 0.18, cy0 + 0.14, badge_d, badge_d, size=11, bold=True,
                 color=WHITE, align=PP_ALIGN.CENTER, valign="center")
        pill_x = cx0 + 0.18 + badge_d + 0.12
        pill_w = card_w - (pill_x - cx0) - 0.18
        add_rect(slide, pill_x, cy0 + 0.145, pill_w, 0.24, accent)
        add_text(slide, label, pill_x, cy0 + 0.145, pill_w, 0.24, size=8, bold=True,
                 color=WHITE, align=PP_ALIGN.CENTER, valign="center")
        add_text(slide, headline, cx0 + 0.18, cy0 + 0.50, card_w - 0.34, 0.24,
                 size=11.5, bold=True, color=NAVY, shrink_to_fit=True)
        add_text(slide, desc, cx0 + 0.18, cy0 + 0.75, card_w - 0.34, 0.40,
                 size=8.5, color=GRAY3, shrink_to_fit=True)



